import squizLayoutStoryRenderer from '@ntgovernment/squiz-factory/plugins/squizLayoutStoryRenderer';
import templateString from './container.hbs?raw';
import manifest from './manifest.json';

const CONTAINER_DOCUMENTATION = `
    <div>
        <p>The container layout is the core layout to wrap components and wysiwyg.</p>
        <p>It fills the space it is in and becomes a centered column on large screen widths.</p>
    </div>
    <div style="background: rgb(200 200 200 / .5)">
        <p>Each component or other direct sibling will be given padding.</p>
    </div>
`

const squiz = squizLayoutStoryRenderer(templateString);

export default {
    title: 'dxp/layouts/container',
    parameters: {
        layout: 'fullscreen',
    },
}

const baseArgs = {
  content: CONTAINER_DOCUMENTATION,
  background: manifest.properties.background.default,
  verticalSpacing: manifest.properties.verticalSpacing.default,
};

const argTypes = {
    content: {
      control: { type: 'text' },
    },
    background: {
      control: {
        type: 'select',
        labels: manifest.properties.background.oneOf.reduce((acc, curr) => {
          acc[curr.const] = curr.title;
          return acc;
        }, {}),
      },
      options: manifest.properties.background.oneOf.map(_ => _.const),
    },
    verticalSpacing: {
      control: {
        type: 'select',
        labels: manifest.properties.verticalSpacing.oneOf.reduce((acc, curr) => {
          acc[curr.const] = curr.title;
          return acc;
        }, {}),
      },
      options: manifest.properties.verticalSpacing.oneOf.map(_ => _.const),
    },
  };

export const Default = {
  render: () => {
        const { content, background, verticalSpacing } = baseArgs;
        return squiz({
            zones: { content },
            properties: { background, verticalSpacing },
        })
    }
}

export const ConfigurationTester = {
  render: ({ content, background, verticalSpacing }) =>
    squiz({
      zones: { content: 'content' },
      properties: { background, verticalSpacing },
    }),
    args: baseArgs,
    argTypes
}